// =====================================================================
//  Estado de los servicios: base de datos y configuración de la IA.
//  Con ?ia=1 además se hace una consulta real de prueba al modelo.
// =====================================================================
const bd = $input.first().json;
const consulta = $('GET /salud').first().json.query ?? {};
const proveedor = String($env.AI_PROVIDER || 'anthropic').trim().toLowerCase();
const modelo = $env.AI_MODEL || (proveedor === 'anthropic' ? 'claude-opus-5-5' : 'llama3.2');

const ia = {
  proveedor,
  modelo,
  configurada: proveedor === 'anthropic' ? Boolean($env.AI_API_KEY) : proveedor === 'openai',
  endpoint:
    proveedor === 'openai'
      ? $env.AI_BASE_URL || 'http://host.docker.internal:11434/v1'
      : $env.AI_BASE_URL || 'https://api.anthropic.com',
};

return [
  {
    json: {
      probarIa: ['1', 'true', 'si'].includes(String(consulta.ia ?? '').toLowerCase()),
      data: {
        servicio: 'ok',
        hora_campus: bd.hora_campus,
        base_de_datos: { conectada: true, registros: bd.registros },
        ia,
      },
    },
  },
];

// Consulta mínima para comprobar que el proveedor de IA responde
return [
  {
    json: {
      tarea: 'prueba_conexion',
      sistema: 'Eres un verificador de conexión. Responde solo con el JSON solicitado.',
      mensaje: 'Confirma que recibiste este mensaje respondiendo con estado "listo".',
      esquema: {
        type: 'object',
        additionalProperties: false,
        required: ['estado'],
        properties: { estado: { type: 'string', enum: ['listo'] } },
      },
      max_tokens: 2000,
      inicio: Date.now(),
    },
  },
];

// Agrega el resultado de la prueba real de IA al estado de los servicios
const salud = $('Estado de los servicios').first().json.data;
const inicio = $('Consulta de prueba').first().json.inicio;
const ia = $input.first().json;

const prueba = {
  ok: ia.ok === true && ia.datos?.estado === 'listo',
  latencia_ms: Date.now() - inicio,
  modelo_respondio: ia.modelo ?? null,
  error: ia.ok === true ? null : `${ia.error ?? 'sin respuesta'}${ia.detalle ? `: ${ia.detalle}` : ''}`,
};

return [{ json: { data: { ...salud, ia: { ...salud.ia, prueba } } } }];

