SELECT json_build_object(
  'categorias', (SELECT json_agg(c ORDER BY c.nombre) FROM categorias_incidencia c),
  'areas', (SELECT json_agg(a ORDER BY a.nombre) FROM areas_responsables a),
  'prioridades', json_build_array('critica', 'alta', 'media', 'baja'),
  'estados_incidencia', json_build_array('abierta', 'en_proceso', 'resuelta', 'cerrada')
) AS data;

